		Addr:                addr,
		Handler:             handler,
		ReadHeaderTimeout:   5 * time.Second,
		ReadTimeout:         10 * time.Second,
		WriteTimeout:        10 * time.Second,
		IdleTimeout:         60 * time.Second,
		MaxHeaderBytes:      1 << 20,
		MaxHeaderValueCount: 100,
	}
}

func accountsHandler(accounts []Account) func(http.ResponseWriter, *http.Request) {
	return func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		isHealth := path == "/healthz"
		isList := path == accountsPath
		isAccount := isAccountPath(path)

		if !isHealth && !isList && !isAccount {
			http.NotFound(w, r)
			return
		}
		if r.Method != http.MethodGet {
